/**
 * @name Path traversal in file serving
 * @description Serving files based on user input without proper validation can allow path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User-controlled input from web requests
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["path", "query", "match_info", "rel_url"] and
      source = attr
    )
    or
    // Request parameters
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("Request").getReturn().getMember(["query", "match_info"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations that could be vulnerable to path traversal
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember("path").getMember(["join", "exists"]).getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from user input $@.", source.getNode(), "here"

/**
 * @name Command injection
 * @description Executing system commands with user-controlled input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Server-Side Request Forgery (SSRF)
 * @description Making HTTP requests to user-controlled URLs can lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("aiohttp").getMember("ClientSession").getReturn().getMember(["get", "post", "put", "delete", "patch", "head", "options", "request"]).getACall() or
        call = API::moduleImport("aiohttp").getMember(["get", "post", "put", "delete", "patch", "head", "options", "request"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability from $@.", source.getNode(), "user input"

/**
 * @name HTTP header injection
 * @description Constructing HTTP headers with user-controlled input can lead to header injection attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Setting headers in responses or requests
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["add_header", "set_cookie", "__setitem__"] and
      sink = call.getArg(_)
    )
  }
}

